def compute(vars):
    nuclear_volume = vars["v1"]
    decrease_in_net_revenue = vars["v2"]
    if decrease_in_net_revenue == 0:
        return None
    value = -nuclear_volume / decrease_in_net_revenue * 100
    return {
        "value": value,
        "trace": {
            "nuclear_volume": nuclear_volume,
            "decrease_in_net_revenue": decrease_in_net_revenue,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
